import{_ as t,o as s,c as e,a2 as n}from"./chunks/framework.CvydjLy7.js";const k=JSON.parse('{"title":"11.5 CDS：把类加载的结果存下来","description":"","frontmatter":{"title":"11.5 CDS：把类加载的结果存下来"},"headers":[{"level":3,"title":"Java 21 上用什么","slug":"java-21-上用什么","link":"#java-21-上用什么","children":[]},{"level":3,"title":"归档里有什么、缺什么","slug":"归档里有什么、缺什么","link":"#归档里有什么、缺什么","children":[]},{"level":3,"title":"效果","slug":"效果","link":"#效果","children":[]},{"level":3,"title":"归档的三个约束","slug":"归档的三个约束","link":"#归档的三个约束","children":[]}],"relativePath":"ch11/05.md","filePath":"ch11/05.md","lastUpdated":1789497795000}'),i={name:"ch11/05.md"};function p(l,a,d,r,h,o){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="_11-5-cds-把类加载的结果存下来" tabindex="-1">11.5 CDS：把类加载的结果存下来 <a class="header-anchor" href="#_11-5-cds-把类加载的结果存下来" aria-label="Permalink to &quot;11.5 CDS：把类加载的结果存下来&quot;">​</a></h1><p>AOT 解决的是“Spring 怎么算 Bean 定义”，CDS（Class Data Sharing）解决的是另一个问题：<strong>JVM 每次启动都要读一遍几千个 class 文件、解析、验证、塞进元空间。</strong></p><p>CDS 的思路很直白：事先跑一次应用，把启动过程中加载过的类在内存里的形态存成一个归档文件，之后启动直接映射这个文件，跳过解析和验证。</p><h3 id="java-21-上用什么" tabindex="-1">Java 21 上用什么 <a class="header-anchor" href="#java-21-上用什么" aria-label="Permalink to &quot;Java 21 上用什么&quot;">​</a></h3><p>Java 24 引入的 AOT cache（<code>-XX:AOTCacheOutput</code>）是 CDS 的继任者，但那个需要 Java 25 及以上。本教程的基线是 Java 21 LTS，所以用的是 CDS：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 训练运行：启动一次应用，把加载过的类归档下来</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -XX:ArchiveClassesAtExit=application.jsa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">       -Dspring.context.exit=onRefresh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">       -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> activity-server-1.0.0.jar</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 正式运行：挂上归档</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -XX:SharedArchiveFile=application.jsa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> activity-server-1.0.0.jar</span></span></code></pre></div><p>两个参数值得解释：</p><p><code>-XX:ArchiveClassesAtExit=application.jsa</code> 是 JDK 的动态归档开关，进程退出时把这次加载的类写成归档。</p><p><code>-Dspring.context.exit=onRefresh</code> 是 Spring Boot 提供的属性，让应用在容器 refresh 完成之后直接退出。训练运行的目的只是“让类被加载”，不需要真的把服务跑起来，这个属性避免训练运行卡在常驻状态。官方文档里 Dockerfile 的写法用的也是它。</p><p>还有一个前置条件容易漏：<strong>归档必须在解压形态下生成，也必须用在解压形态上</strong>。对可执行 jar 做训练运行，归档挂上去是没有效果的——因为可执行 jar 里的类是嵌套 jar，进不了归档。官方文档明确写了这一点：</p><blockquote><p>You have to use the cache file with the extracted form of the application, otherwise it has no effect.</p></blockquote><h3 id="归档里有什么、缺什么" tabindex="-1">归档里有什么、缺什么 <a class="header-anchor" href="#归档里有什么、缺什么" aria-label="Permalink to &quot;归档里有什么、缺什么&quot;">​</a></h3><p>训练运行会打印大量这样的警告：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[warning][cds] Skipping jdk/proxy2/$Proxy120: Unsupported location</span></span>
<span class="line"><span>[warning][cds] Skipping jdk/proxy2/$Proxy161: Unsupported location</span></span>
<span class="line"><span>[warning][cds] Skipping org/hibernate/type/format/jakartajson/JsonBJsonFormatMapper: Failed verification</span></span></code></pre></div><p>统计一下被跳过的类：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>235 条 Skipping 记录</span></span>
<span class="line"><span></span></span>
<span class="line"><span>158  jdk/proxy2/            JDK 动态代理</span></span>
<span class="line"><span>  8  jdk/proxy1/            JDK 动态代理</span></span>
<span class="line"><span>  6  net/bytebuddy/         ByteBuddy 生成的类</span></span>
<span class="line"><span>  6  com/example/activity/domain/    Hibernate 增强后的实体</span></span>
<span class="line"><span>  5  jdk/internal/reflect/</span></span></code></pre></div><p>这里能看出 CDS 的能力边界：<strong>运行期生成的类比构建期固定的类更吃亏</strong>。动态代理的字节码在生成时才知道，没法进归档；Hibernate 增强过的实体类也是同理，<code>Failed verification</code> 说明字节码校验没过。</p><p>这些警告不影响使用，但如果归档后启动加速不明显，可以先看跳过了多少——跳得越多，归档的收益越小。</p><h3 id="效果" tabindex="-1">效果 <a class="header-anchor" href="#效果" aria-label="Permalink to &quot;效果&quot;">​</a></h3><table tabindex="0"><thead><tr><th>形态</th><th>三次耗时（秒）</th><th>中位数</th><th>相对基线</th></tr></thead><tbody><tr><td>可执行 jar</td><td>4.643 / 4.799 / 4.825</td><td>4.80</td><td>—</td></tr><tr><td>解压布局</td><td>3.765 / 3.767 / 3.897</td><td>3.77</td><td>−21%</td></tr><tr><td>解压 + CDS</td><td>2.209 / 2.284 / 2.396</td><td>2.28</td><td>−52%</td></tr></tbody></table><p>CDS 单独带来约 1.5 秒的提升，比解压更明显。</p><p>再看 AOT 和 CDS 叠加：</p><table tabindex="0"><thead><tr><th>形态</th><th>三次耗时（秒）</th><th>中位数</th><th>相对基线</th></tr></thead><tbody><tr><td>AOT jar</td><td>3.810 / 3.865 / 3.878</td><td>3.87</td><td>−19%</td></tr><tr><td>AOT + 解压</td><td>2.982 / 3.052 / 3.224</td><td>3.05</td><td>−36%</td></tr><tr><td>AOT + 解压 + CDS</td><td>1.624 / 1.647 / 1.760</td><td>1.65</td><td>−66%</td></tr></tbody></table><p><strong>1.65 秒</strong>。从 4.8 秒压到这个数字，全程没有改一行业务代码，也没有引入任何外部依赖——只是换了打包形态，让 JVM 少做了两次重复劳动。</p><h3 id="归档的三个约束" tabindex="-1">归档的三个约束 <a class="header-anchor" href="#归档的三个约束" aria-label="Permalink to &quot;归档的三个约束&quot;">​</a></h3><p>CDS 不是随时都能用的，有三条硬约束：</p><p><strong>归档与平台绑定。</strong> 归档里存的是内存映像，包含平台相关的结构。在 macOS 上生成的 <code>.jsa</code> 拿到 Linux 容器里用会直接失败。所以容器场景下，训练运行必须在容器构建阶段完成（11.6 的做法）。</p><p><strong>归档与 JDK 版本绑定。</strong> 换了 JDK 小版本要重新生成，否则可能加载失败。</p><p><strong>应用一变，归档就作废。</strong> 类名、方法签名变了，归档里的内容就对不上。所以生成归档是<strong>构建流程的一部分</strong>，不是一次性操作——每次发布新版本都要重新做训练运行。</p><p><strong>归档的体积也要算进去。</strong> 实测这个应用的 <code>.jsa</code> 是 111 MB，比整个 jar（62MB）还大。如果只是为了让启动快 1.5 秒，就要在镜像里多塞 111MB，这笔账要自己算。11.6 会看到它对镜像大小的实际影响。</p><hr>`,31)])])}const g=t(i,[["render",p]]);export{k as __pageData,g as default};
